/// Birth moment of the first person. Each subject carries its own school switches, so two charts built under different conventions can still be compared.
extension type CalculateBaziCompatibilityRequestPersonA.fromJson(
  Map<String, Object?> json
)
    implements Object {
  /// Builds the object to send.
  CalculateBaziCompatibilityRequestPersonA({
    required String date,
    required String time,
    required NumOrString timezone,
    num? latitude,
    num? longitude,
    DayBoundary? dayBoundary,
    YearBoundary? yearBoundary,
    HourClock? hourClock,
  }) : json = <String, Object?>{
         'date': date,
         'time': time,
         'timezone': timezone,
         'latitude': ?latitude,
         'longitude': ?longitude,
         'dayBoundary': ?dayBoundary?.wire,
         'yearBoundary': ?yearBoundary?.wire,
         'hourClock': ?hourClock?.wire,
       };
}

/// Birth moment of the second person.
extension type CalculateBaziCompatibilityRequestPersonB.fromJson(
  Map<String, Object?> json
)
    implements Object {
