extension type CalculateBaziCompatibilityResponsePersonAPillarsItemHiddenStemsItem.fromJson(
  Map<String, Object?> json
)
    implements Object {
  /// The stem stored in the branch.
  CalculateBaziCompatibilityResponsePersonAPillarsItemHiddenStemsItemStem
  get stem => read(
