  num get overallScore => read(json, 'overallScore', asNum);

  /// Compatibility rating label. One of: Highly Aligned, Well Aligned, Moderately Aligned, Misaligned, Opposed.
  String get rating => read(json, 'rating', asString);

  /// Per-cycle compatibility analysis for physical, emotional, and intellectual cycles.
  Map<String, CalculateBioCompatibilityResponseCyclesValue> get cycles => read(
    json,
    'cycles',
    mapOf(model(CalculateBioCompatibilityResponseCyclesValue.fromJson)),
  );

