  List<String> get strengths => read(json, 'strengths', listOf(asString));

  /// Potential relationship challenges to be aware of.
  List<String> get challenges => read(json, 'challenges', listOf(asString));

  /// Practical relationship guidance based on the combined cycle analysis.
  String get advice => read(json, 'advice', asString);

  /// `dailySync`
  CalculateBioCompatibilityResponseDailySync get dailySync => read(
    json,
    'dailySync',
    model(CalculateBioCompatibilityResponseDailySync.fromJson),
  );
}

/// How the two people sit against each other on one cycle: each value, the gap between them, an alignment score, the pair phase, and a sentence on what it means for the relationship.
