extension type CalculateGematriaResponse.fromJson(Map<String, Object?> json)
    implements Object {
  /// `input`
  CalculateGematriaResponseInput get input =>
      read(json, 'input', model(CalculateGematriaResponseInput.fromJson));

  /// Every Hebrew spelling the input can be written as, greedy parse first. One entry when Hebrew was sent, since there is nothing to choose.
  List<CalculateGematriaResponseHebrewFormsItem> get hebrewForms => read(
    json,
    'hebrewForms',
    listOf(model(CalculateGematriaResponseHebrewFormsItem.fromJson)),
  );

  /// `chosen`
  CalculateGematriaResponseChosen get chosen =>
      read(json, 'chosen', model(CalculateGematriaResponseChosen.fromJson));

  /// Every requested cipher applied to the chosen spelling, in catalogue order, each named as the catalogue names it. Only computed ciphers appear, so every row carries a number.
  List<CalculateGematriaResponseValuesItem> get values => read(
    json,
    'values',
    listOf(model(CalculateGematriaResponseValuesItem.fromJson)),
  );

  /// The two substitution transformations applied to the chosen spelling. Each exchanges letters and returns a new word, so the interesting output is often the string rather than the number.
  List<CalculateGematriaResponseTransformationsItem> get transformations =>
      read(
        json,
        'transformations',
        listOf(model(CalculateGematriaResponseTransformationsItem.fromJson)),
      );

  /// The Latin alphabet ciphers applied to the Latin text. Present only when latinCiphers was set and a Latin text was sent.
  List<CalculateGematriaResponseLatinValuesItem>? get latinValues => readOrNull(
    json,
    'latinValues',
    listOf(model(CalculateGematriaResponseLatinValuesItem.fromJson)),
  );

  /// Curated words whose standard value equals the chosen spelling. Matching is on the standard reading only, because that is the relation the classical method works with. Empty when nothing matches, which is the ordinary case.
  List<CalculateGematriaResponseMatchesItem> get matches => read(
    json,
    'matches',
    listOf(model(CalculateGematriaResponseMatchesItem.fromJson)),
  );

  /// `conventions`
  CalculateGematriaResponseConventions get conventions => read(
    json,
    'conventions',
    model(CalculateGematriaResponseConventions.fromJson),
  );
}

extension type CalculateGematriaResponseChosen.fromJson(
  Map<String, Object?> json
)
    implements Object {
  /// The spelling the values and matches on this response were taken from.
  String get hebrew => read(json, 'hebrew', asString);

  /// Why this spelling was chosen over the others.
  String get rule => read(json, 'rule', asString);
}

extension type CalculateGematriaResponseConventions.fromJson(
  Map<String, Object?> json
)
    implements Object {
  /// The Latin to Hebrew scheme applied. Absent when the caller sent Hebrew directly.
  String? get transliteration => readOrNull(json, 'transliteration', asString);

  /// Which of the two published methods the name mispar gadol was read as.
  String get misparGadol => read(json, 'misparGadol', asString);

  /// What the substitution transformations returned.
  String get atbashOutput => read(json, 'atbashOutput', asString);
}

extension type CalculateGematriaResponseHebrewFormsItem.fromJson(
  Map<String, Object?> json
)
    implements Object {
  /// One Hebrew spelling the Latin input can be written as. Data, identical in every language.
  String get hebrew => read(json, 'hebrew', asString);

  /// Latin transcription of the Hebrew beside it, produced by one mechanical letter map. It is a label for reading the string back, never a pronunciation claim.
  String get romanization => read(json, 'romanization', asString);

  /// Why this spelling came out of the map: the parse rule first, then one sentence for every reading the scheme applied that the letters alone would not show, so a caller can tell the parses apart.
  String get rule => read(json, 'rule', asString);

  /// Every computed cipher applied to this spelling, in catalogue order. The rows carry no display name, because they are the same ciphers in the same order for every spelling: read the names off the top level values array once.
  List<CalculateGematriaResponseHebrewFormsItemValuesItem> get values => read(
    json,
    'values',
    listOf(model(CalculateGematriaResponseHebrewFormsItemValuesItem.fromJson)),
  );

  /// The per letter breakdown of this spelling under the standard reading.
  List<CalculateGematriaResponseHebrewFormsItemLettersItem> get letters => read(
    json,
    'letters',
    listOf(model(CalculateGematriaResponseHebrewFormsItemLettersItem.fromJson)),
  );
}

extension type CalculateGematriaResponseHebrewFormsItemLettersItem.fromJson(
  Map<String, Object?> json
)
    implements Object {
  /// The Hebrew letter as it stands in the string. Data, identical in every language.
  String get glyph => read(json, 'glyph', asString);

  /// Machine identifier of the letter, always English romanization so it stays safe to compare against in code.
  String get letterId => read(json, 'letterId', asString);

  /// Display name of the letter, in the requested language. Branch on letterId, never on this.
  String get name => read(json, 'name', asString);

  /// True when the glyph is the word final form. Under the finals-500-900 reading the same letter scores differently in final position, which is why this is on the row.
  bool get isFinal => read(json, 'isFinal', asBool);

  /// What this letter contributed under the standard reading, or under the finals reading when one applies.
  num get value => read(json, 'value', asNum);
}

extension type CalculateGematriaResponseHebrewFormsItemValuesItem.fromJson(
  Map<String, Object?> json
)
    implements Object {
  /// Machine identifier of the cipher. Call the ciphers endpoint for the definition, the tradition and the sources behind each one.
  String get id => read(json, 'id', asString);

  /// The number this cipher gives for the string. Always a number: the one catalogued cipher this API does not compute is absent from this array rather than present without a value, so no row here has to be guarded. Its catalogue entry carries computed false and says why.
  num get value => read(json, 'value', asNum);

  /// Other published totals for the same string, ascending. Present only where the cipher is not single valued: letter names have several accepted spellings, so several totals are equally published. Absent otherwise, so a caller can branch on presence.
  List<num>? get alternateValues =>
      readOrNull(json, 'alternateValues', listOf(asNum));

  /// Provenance class of the cipher, one of rabbinic, renaissance-latin, golden-dawn-transliterated or modern. Always English, so it stays safe to compare against in code.
  String get tradition => read(json, 'tradition', asString);

  /// The first published source this cipher was taken from.
  String get source => read(json, 'source', asString);
}

