  List<String> get challenges => read(json, 'challenges', listOf(asString));

  /// Tailored career guidance covering ideal industries, roles, and work environments. Includes specific job titles and explains why certain professional paths align with this number.
  String get career => read(json, 'career', asString);

  /// Love, friendship, and family dynamics. Covers romantic compatibility with other Life Path numbers, communication style, and the key relationship lessons for this number.
  String get relationships => read(json, 'relationships', asString);

  /// Spiritual path, soul lessons, and recommended practices. Explores the deeper purpose behind this number and offers guidance for personal growth and inner alignment.
  String get spirituality => read(json, 'spirituality', asString);
}

extension type CalculateLuckPillarsResponse.fromJson(Map<String, Object?> json)
    implements Object {
  /// Echo of the birth moment the chart was computed from.
  CalculateLuckPillarsResponseBirthData get birthData => read(
    json,
    'birthData',
    model(CalculateLuckPillarsResponseBirthData.fromJson),
  );

  /// The three school conventions this result was computed under. Returned on every BaZi response so a chart is self-describing: two calculators can produce different pillars for one birth and both be correct, and this object says which reading you are holding.
  CalculateLuckPillarsResponseConventions get conventions => read(
    json,
    'conventions',
    model(CalculateLuckPillarsResponseConventions.fromJson),
  );

  /// Echo of the sex sent, which is what selected the direction below.
  String get gender => read(json, 'gender', asString);

  /// Which way the sequence walks the sexagenary cycle. A male born in a yang-stem year and a female born in a yin-stem year run forward, and the other two combinations run backward. Always English, whatever the lang parameter says.
  String get direction => read(json, 'direction', asString);

  /// Age in whole years at which the first luck pillar begins. Counted from the birth instant to the adjacent minor solar term at three days to the year, forward for a forward direction and backward for a reverse one.
  num get startAge => read(json, 'startAge', asNum);

  /// Additional months past startAge, 0 to 11, from the remainder of the same count at one day to four months, rounded once to the nearest month. Calculators that round the whole count to the nearest year will differ from this by up to six months.
  num get startAgeMonths => read(json, 'startAgeMonths', asNum);

  /// Days from the birth instant to the minor solar term the count ran to, before conversion. Published so the start age can be checked rather than taken on trust.
  num get daysToTerm => read(json, 'daysToTerm', asNum);

  /// The minor solar term the count ran to. One of the twelve that also move the month pillar. Always the pinyin identifier, whatever the lang parameter says.
  String get boundaryTerm => read(json, 'boundaryTerm', asString);

  /// Display name of that same term, in the requested language. Always present, and English when lang is en. Several English renderings of a term are in circulation, so treat this as the label and boundaryTerm as the value.
  String get boundaryTermName => read(json, 'boundaryTermName', asString);

  /// The ten-year periods in order, each with the relation its stem holds to the natal Day Master.
  List<CalculateLuckPillarsResponseLuckPillarsItem> get luckPillars => read(
    json,
    'luckPillars',
    listOf(model(CalculateLuckPillarsResponseLuckPillarsItem.fromJson)),
  );

  /// Year-by-year overlay, present only when annualFromYear was sent. Each year names the luck pillar it falls inside.
  List<CalculateLuckPillarsResponseAnnualPillarsItem>? get annualPillars =>
      readOrNull(
        json,
        'annualPillars',
        listOf(model(CalculateLuckPillarsResponseAnnualPillarsItem.fromJson)),
      );

  /// One-paragraph reading of the sequence direction and its start.
  String get summary => read(json, 'summary', asString);
}

