extension type CalculateNameCompatibilityResponse.fromJson(
  Map<String, Object?> json
)
    implements Object {
  /// `first`
  CalculateNameCompatibilityResponseFirst get first => read(
    json,
    'first',
    model(CalculateNameCompatibilityResponseFirst.fromJson),
  );

  /// `second`
  CalculateNameCompatibilityResponseSecond get second => read(
    json,
    'second',
    model(CalculateNameCompatibilityResponseSecond.fromJson),
  );

  /// Every cipher on which the two names give the same number. Empty when they share none, which happens often and carries no traditional reading of its own.
  List<CalculateNameCompatibilityResponseSharedValuesItem> get sharedValues =>
      read(
        json,
        'sharedValues',
        listOf(
          model(CalculateNameCompatibilityResponseSharedValuesItem.fromJson),
        ),
      );

  /// The composite, 0 to 100. A RoxyAPI composite, not a classical measure: no source scores two names against each other, so the components below are published and the number is derivable from them.
  num get score => read(json, 'score', asNum);

  /// Which band the composite falls in: high, moderate or low. Derived from the score, always English.
  String get band => read(json, 'band', asString);

  /// Every component of the composite with its own maximum, so a caller who disagrees with the weighting can recompute rather than argue.
  List<CalculateNameCompatibilityResponseComponentsItem> get components => read(
    json,
    'components',
    listOf(model(CalculateNameCompatibilityResponseComponentsItem.fromJson)),
  );

  /// The composed reading, in the requested language. It states that the score is ours.
  String get reading => read(json, 'reading', asString);

  /// `conventions`
  CalculateNameCompatibilityResponseConventions get conventions => read(
    json,
    'conventions',
    model(CalculateNameCompatibilityResponseConventions.fromJson),
  );
}

