extension type CalculateTransitResponse.fromJson(Map<String, Object?> json)
    implements Object {
  /// The zodiac frame every longitude in this response was computed in, so a cached or forwarded payload is self describing. Sidereal requests report the Lahiri ayanamsa, read at the birth instant; the transit positions use the same named frame resolved at their own instant, which moves by about 50 arcseconds a year. A tropical request reports "tropical" with 0 degrees subtracted, which is the one case a Vedic table can otherwise be rendered in the wrong zodiac with nothing on screen saying so.
  CalculateTransitResponseFrame get frame =>
      read(json, 'frame', model(CalculateTransitResponseFrame.fromJson));

  /// Birth datetime used for the natal chart, echoed as the local civil date and time supplied in the request (YYYY-MM-DDTHH:MM:SS). Combine it with the timezone field to recover the UTC instant.
  String get birthDatetime => read(json, 'birthDatetime', asString);

  /// Transit datetime being analyzed, echoed as the local civil date and time supplied in the request (YYYY-MM-DDTHH:MM:SS). Gochar positions are computed for this moment and overlaid on the natal chart.
  String get transitDatetime => read(json, 'transitDatetime', asString);

  /// All 9 planetary positions from the natal (birth) chart.
  List<CalculateTransitResponseNatalPlanetsItem> get natalPlanets => read(
    json,
    'natalPlanets',
    listOf(model(CalculateTransitResponseNatalPlanetsItem.fromJson)),
  );

  /// Current planetary positions overlaid on the natal chart with house placements, aspects, and the Gochara Kaksha verdict for each graha.
  List<CalculateTransitResponseTransitingPlanetsItem> get transitingPlanets =>
      read(
        json,
        'transitingPlanets',
        listOf(model(CalculateTransitResponseTransitingPlanetsItem.fromJson)),
      );

  /// Highlighted transits from slow-moving planets (Jupiter, Saturn, Rahu, Ketu), most impactful for Gochar analysis.
  List<CalculateTransitResponseKeyTransitsItem> get keyTransits => read(
    json,
    'keyTransits',
    listOf(model(CalculateTransitResponseKeyTransitsItem.fromJson)),
  );
}

/// The zodiac frame every longitude in this response was computed in, so a cached or forwarded payload is self describing. Sidereal requests report the Lahiri ayanamsa, read at the birth instant; the transit positions use the same named frame resolved at their own instant, which moves by about 50 arcseconds a year. A tropical request reports "tropical" with 0 degrees subtracted, which is the one case a Vedic table can otherwise be rendered in the wrong zodiac with nothing on screen saying so.
extension type CalculateTransitResponseFrame.fromJson(Map<String, Object?> json)
    implements Object {
  /// Sidereal frame this chart was cast in, echoing the ayanamsa request field. "lahiri" when the field was omitted.
  String get ayanamsa => read(json, 'ayanamsa', asString);

  /// Degrees actually subtracted from every tropical longitude to produce this chart, read at the birth instant. Subtract it back to recover the tropical positions, or compare it against your reference software to confirm you are in the same frame before chasing a placement difference.
  num get ayanamsaDegrees => read(json, 'ayanamsaDegrees', asNum);
}

