extension type CalculateTransitResponseTransitingPlanetsItem.fromJson(
  Map<String, Object?> json
)
    implements Object {
  /// Transiting planet name.
  String get name => read(json, 'name', asString);

  /// Current sidereal longitude of the transiting planet.
  num get longitude => read(json, 'longitude', asNum);

  /// Current zodiac sign of the transiting planet.
