extension type CalculateTzolkinResponse.fromJson(Map<String, Object?> json)
    implements Object {
  /// Machine identifier of the Tzolkin day sign, always lowercase ASCII Yucatec whatever the lang parameter says, so it stays safe to compare against in code. The twenty ids run imix, ik, akbal, kan, chikchan, kimi, manik, lamat, muluk, ok, chuwen, eb, ben, ix, men, kib, kaban, etznab, kawak, ajaw.
  String get daySign => read(json, 'daySign', asString);

  /// Display name of the day sign in the standard Maya orthography, where the ejective is written with a modifier letter rather than a typewriter quote. A proper noun carried as data, so it is identical under every lang.
  String get daySignName => read(json, 'daySignName', asString);

  /// The sixteenth century Yucatec spelling of the same sign, which is the form most printed reference tables and older sources use. Useful for matching a name a reader copied out of a book.
  String get daySignClassic => read(json, 'daySignClassic', asString);

  /// The Kʼicheʼ name of the same day from the living highland daykeeping tradition, which is the vocabulary a nawal reading in Guatemala uses. A parallel naming tradition rather than a translation, so it is identical under every lang.
  String get daySignKiche => read(json, 'daySignKiche', asString);

  /// The Tzolkin coefficient, 1 to 13. This is the classical day number that runs alongside the twenty signs; it is not a rank and a 13 is not better than a 1. Nine of the thirteen carry a recorded character, which is returned separately.
  num get number => read(json, 'number', asNum);

  /// The thirteen day period this day belongs to. The trecena is the unit a daykeeper reads a run of days in, and the sign it opens on is what gives the whole period its character.
  CalculateTzolkinResponseTrecena get trecena =>
      read(json, 'trecena', model(CalculateTzolkinResponseTrecena.fromJson));

  /// Echo of the date the day was resolved from, in proleptic Gregorian.
  String get date => read(json, 'date', asString);

  /// The composed nawal reading for this day: the sign, what the coefficient contributes, and what the sign does well and badly.
  CalculateTzolkinResponseReading get reading =>
      read(json, 'reading', model(CalculateTzolkinResponseReading.fromJson));

  /// The conventions this answer was computed under, echoed so the result is self describing. Only the correlation is echoed here, because it is the only switch this route takes.
  CalculateTzolkinResponseConventions get conventions => read(
    json,
    'conventions',
    model(CalculateTzolkinResponseConventions.fromJson),
  );
}

/// The conventions this answer was computed under, echoed so the result is self describing. Only the correlation is echoed here, because it is the only switch this route takes.
extension type CalculateTzolkinResponseConventions.fromJson(
  Map<String, Object?> json
)
    implements Object {
  /// The correlation constant actually applied, whether it was requested or defaulted. Store this beside any Maya date you persist: the same civil date resolves to a different Long Count under each constant, and a date with no correlation recorded cannot be reproduced.
  String get correlation => read(json, 'correlation', asString);
}

/// The composed nawal reading for this day: the sign, what the coefficient contributes, and what the sign does well and badly.
extension type CalculateTzolkinResponseReading.fromJson(
  Map<String, Object?> json
)
    implements Object {
  /// The sign in one composed sentence: its name in both naming traditions, what it is about, and the glyph reading behind it. Composed per request from the sign components rather than stored whole, which is why it stays consistent with every other reading in the response.
  String get keynote => read(json, 'keynote', asString);

  /// What the coefficient contributes. Nine of the thirteen carry a recorded character, banded as gentle, indifferent or violent; the other four carry none and this field says so rather than inventing one. The band ids are the source vocabulary, so violent names the days reserved for strong ceremony and defence and is not a warning.
  String get numberReading => read(json, 'numberReading', asString);

  /// Machine identifier of the recorded character of the coefficient: gentle, indifferent or violent. ABSENT for coefficients 4, 5, 6 and 10, which have no recorded character in any consulted source. Always English so it stays safe to switch on.
  String? get numberBand => readOrNull(json, 'numberBand', asString);

  /// What the sign does well, as full sentences rather than keywords.
  List<String> get strengths => read(json, 'strengths', listOf(asString));

  /// Where the same temperament costs the sign something. Each one is the shadow of a strength above rather than an unrelated flaw.
  List<String> get challenges => read(json, 'challenges', listOf(asString));

  /// The one thing worth doing differently under this sign.
  String get guidance => read(json, 'guidance', asString);
}

/// The thirteen day period this day belongs to. The trecena is the unit a daykeeper reads a run of days in, and the sign it opens on is what gives the whole period its character.
extension type CalculateTzolkinResponseTrecena.fromJson(
  Map<String, Object?> json
)
    implements Object {
  /// Which of the twenty thirteen day periods this day falls in, 1 to 20. Trecena 1 opens on 1 Imix.
  num get number => read(json, 'number', asNum);

  /// Position of this day inside its trecena, 1 to 13. Always equal to the coefficient, because a trecena is exactly one run of the coefficient.
  num get dayOfTrecena => read(json, 'dayOfTrecena', asNum);

  /// Machine identifier of the day sign the trecena opens on, which the tradition reads as colouring all thirteen of its days.
  String get rulingSign => read(json, 'rulingSign', asString);

  /// Display name of the sign the trecena opens on. A proper noun carried as data.
  String get rulingSignName => read(json, 'rulingSignName', asString);
}

extension type CalculateVariablesResponse.fromJson(Map<String, Object?> json)
    implements Object {
  /// The four Variable arrows: Determination and Environment from the design side, Perspective and Motivation from the personality side. Together they form the Rave Variables / Primary Health System layer that sits beneath Type, Strategy, Authority, and Profile.
  List<CalculateVariablesResponseArrowsItem> get arrows => read(
    json,
    'arrows',
    listOf(model(CalculateVariablesResponseArrowsItem.fromJson)),
  );

  /// True only when all four arrows are confident. A single knife-edge arrow makes the whole configuration uncertain.
  bool get confident => read(json, 'confident', asBool);

  /// Boundary margin in degrees of ecliptic longitude used for the per-arrow confidence flag, the solar arc over a few minutes of clock time. An activation within this distance of a Color or Tone boundary is flagged low-confidence.
  num get confidenceMarginDeg => read(json, 'confidenceMarginDeg', asNum);

  /// What the Base layer is. Returned once at the top level rather than repeated on every arrow, since the Base layer is the same concept for all four. No per-Base meaning is returned: every one in circulation traces back to a single origin, so it fails the two-source bar this package holds.
  String get baseDescription => read(json, 'baseDescription', asString);
}

extension type CalculateVariablesResponseArrowsItem.fromJson(
  Map<String, Object?> json
)
    implements Object {
  /// Stable arrow identifier. One of determination, environment, perspective, motivation.
  String get key => read(json, 'key', asString);

  /// Arrow name. Determination is the top-left arrow governing the Primary Health System and digestion, Environment the bottom-left arrow, Perspective the bottom-right arrow also called View, and Motivation the top-right arrow. Always English, whatever the lang parameter says. Use nameLocalized for anything a reader sees.
  String get name => read(json, 'name', asString);

  /// Arrow name in the requested language, for display only. Present only when lang is set to a language other than English, since in English it would repeat its canonical partner field exactly. Never compare against this value, compare against the canonical field beside it.
  String? get nameLocalized => readOrNull(json, 'nameLocalized', asString);

  /// Which half of the advanced layer the arrow belongs to. Primary Health System covers the body-side Determination and Environment arrows, Rave Psychology covers the mind-side Perspective and Motivation arrows. Always English, whatever the lang parameter says, so it stays safe to compare against in code. Use layerLocalized for anything a reader sees.
  String get layer => read(json, 'layer', asString);

  /// Layer name in the requested language, for display only. Present only when lang is set to a language other than English, since in English it would repeat its canonical partner field exactly. Never compare against this value, compare against the canonical field beside it.
  String? get layerLocalized => readOrNull(json, 'layerLocalized', asString);

  /// Position of the arrow at the head of the bodygraph. One of Top left, Bottom left, Top right, Bottom right. Always English, whatever the lang parameter says, so it stays safe to compare against in code. Use positionLocalized for anything a reader sees.
  String get position => read(json, 'position', asString);

  /// Arrow position name in the requested language, for display only. Present only when lang is set to a language other than English, since in English it would repeat its canonical partner field exactly. Never compare against this value, compare against the canonical field beside it.
  String? get positionLocalized =>
      readOrNull(json, 'positionLocalized', asString);

  /// The single activation, body and chart side, that this arrow is derived from.
  CalculateVariablesResponseArrowsItemActivation get activation => read(
    json,
    'activation',
    model(CalculateVariablesResponseArrowsItemActivation.fromJson),
  );

  /// Color number from 1 to 6, the substructure level one octave finer than the line. Color selects the arrow theme, for example the determination family or the motivation.
  num get color => read(json, 'color', asNum);

  /// Tone number from 1 to 6, the substructure level beneath Color. Tone sets the arrow direction: tones 1 to 3 face left, tones 4 to 6 face right.
  num get tone => read(json, 'tone', asNum);

  /// Base number from 1 to 5, the finest published subdivision of the wheel. Returned for completeness but treated as informational, since it is finer than most birth times can resolve.
  num get base => read(json, 'base', asNum);

  /// Arrow direction derived from the Tone. left for tones 1 to 3, right for tones 4 to 6.
  String get direction => read(json, 'direction', asString);

  /// Name of the Color theme for this arrow, for example a determination family such as Touch, an environment such as Mountains, a perspective such as Personal, or a motivation such as Hope. Always English, whatever the lang parameter says. Use colorLabelLocalized for anything a reader sees.
  String get colorLabel => read(json, 'colorLabel', asString);

  /// Color theme name in the requested language, for display only. Present only when lang is set to a language other than English, since in English it would repeat its canonical partner field exactly. Never compare against this value, compare against the canonical field beside it.
  String? get colorLabelLocalized =>
      readOrNull(json, 'colorLabelLocalized', asString);

  /// Keynote of the arrow direction for this arrow, for example Active or Passive for Determination, Focused or Peripheral for Perspective. Always English, whatever the lang parameter says. Use directionLabelLocalized for anything a reader sees.
  String get directionLabel => read(json, 'directionLabel', asString);

  /// Arrow direction keynote in the requested language, for display only. Present only when lang is set to a language other than English, since in English it would repeat its canonical partner field exactly. Never compare against this value, compare against the canonical field beside it.
  String? get directionLabelLocalized =>
      readOrNull(json, 'directionLabelLocalized', asString);

  /// What this arrow is and what it governs.
  String get description => read(json, 'description', asString);

  /// What the layer this arrow belongs to governs, the body side or the mind side.
  String get layerDescription => read(json, 'layerDescription', asString);

  /// Meaning of the Color for THIS arrow. The same Color number means something different under Determination than under Motivation, so this is the reading of colorLabel in context, not a generic gloss.
  String get colorMeaning => read(json, 'colorMeaning', asString);

  /// Meaning of the Tone. The six Tones are shared across all four arrows: the arrow does not change the Tone, it changes what the Tone qualifies.
  String get toneMeaning => read(json, 'toneMeaning', asString);

  /// Meaning of the left or right direction for THIS arrow, the reading of directionLabel.
  String get directionMeaning => read(json, 'directionMeaning', asString);

  /// Name of the Base. Informational only: the Base is finer than any civil birth time can resolve. Always English, whatever the lang parameter says. Use baseNameLocalized for anything a reader sees.
  String get baseName => read(json, 'baseName', asString);

  /// Base name in the requested language, for display only. Present only when lang is set to a language other than English, since in English it would repeat its canonical partner field exactly. Never compare against this value, compare against the canonical field beside it.
  String? get baseNameLocalized =>
      readOrNull(json, 'baseNameLocalized', asString);

  /// Cognition, the strongest sense, read off the Determination Tone. Present on the determination arrow ONLY: no authority supports reading Cognition from the other three arrows, so it is omitted rather than invented.
  CalculateVariablesResponseArrowsItemCognition? get cognition => readOrNull(
    json,
    'cognition',
    model(CalculateVariablesResponseArrowsItemCognition.fromJson),
  );

  /// Whether this arrow is far enough from a Color or Tone boundary to be reliable. When false the activation sits on a knife edge where the Color label or the arrow direction could flip with a more precise birth time, and the arrow should not be presented as fact.
  bool get confident => read(json, 'confident', asBool);
}

