  List<GenerateBaziChartResponsePillarsItemHiddenStemsItem> get hiddenStems =>
      read(
        json,
        'hiddenStems',
        listOf(
          model(GenerateBaziChartResponsePillarsItemHiddenStemsItem.fromJson),
        ),
      );

  /// Na Yin sound element of the pillar, an older elemental reading assigned to each of the 30 stem-and-branch pairs. The hanzi name sits beside it in naYinChinese.
  String get naYin => read(json, 'naYin', asString);

  /// The Na Yin name in hanzi. Identical under every lang.
  String get naYinChinese => read(json, 'naYinChinese', asString);

  /// Element the Na Yin resolves to. Independent of the stem element and often different from it, which is why it is reported separately rather than folded in. Always English, whatever the lang parameter says. Use naYinElementLocalized for anything a reader sees.
  String get naYinElement => read(json, 'naYinElement', asString);

  /// Na Yin element name in the requested language, for display only. Present only when lang is set to a language other than English, since in English it would repeat its canonical partner field exactly. Never compare against this value, compare against the canonical field beside it.
  String? get naYinElementLocalized =>
      readOrNull(json, 'naYinElementLocalized', asString);
}

