extension type GenerateBirthProfileResponse.fromJson(Map<String, Object?> json)
    implements Object {
  /// The birth moment this answer was computed from.
  GenerateBirthProfileResponseBirthData get birthData => read(
    json,
    'birthData',
    model(GenerateBirthProfileResponseBirthData.fromJson),
  );

  /// The Hebrew date of the birth.
  GenerateBirthProfileResponseHebrewDate get hebrewDate => read(
    json,
    'hebrewDate',
    model(GenerateBirthProfileResponseHebrewDate.fromJson),
  );

  /// The next Hebrew birthday from targetDate (the current UTC date when omitted), the anniversary of hebrewDate. Three Hebrew dates are missing from some years, and where the anniversary moves to is a matter of community practice rather than arithmetic, so the field is null with a note rather than a guess.
  GenerateBirthProfileResponseHebrewBirthday get hebrewBirthday => read(
    json,
    'hebrewBirthday',
    model(GenerateBirthProfileResponseHebrewBirthday.fromJson),
  );

  /// The three names: two read from the day of birth by two different cycles, and one from the hour. All three are described, never invoked.
  List<GenerateBirthProfileResponseAngelsItem> get angels => read(
    json,
    'angels',
    listOf(model(GenerateBirthProfileResponseAngelsItem.fromJson)),
  );

  /// The sephirah reached from the value of the Hebrew date written in letters. A numerical convention rather than a classical rule, offered as a way into the tree.
  GenerateBirthProfileResponseSephirah get sephirah => read(
    json,
    'sephirah',
    model(GenerateBirthProfileResponseSephirah.fromJson),
  );

  /// The conventions this answer was computed under, echoed so it can be reproduced.
  GenerateBirthProfileResponseConventions get conventions => read(
    json,
    'conventions',
    model(GenerateBirthProfileResponseConventions.fromJson),
  );
}

extension type GenerateBirthProfileResponseAngelsItem.fromJson(
  Map<String, Object?> json
)
    implements Object {
  /// What this name is read from: body and character both come from the day of birth by two different cycles, and spirit comes from the hour. Always English, so it stays safe to compare against in code.
  String get role => read(json, 'role', asString);

  /// Index of the name, 1 to 72.
  num get number => read(json, 'number', asNum);

  /// The name in Hebrew. Data, identical in every language.
  String get name => read(json, 'name', asString);

  /// Latin transcription of the Hebrew, from the one mechanical letter map.
  String get romanization => read(json, 'romanization', asString);

  /// The Latin spelling the published tables print, which is the searchable name.
  String get traditionalName => read(json, 'traditionalName', asString);

  /// The angelic choir the name belongs to under the published Renaissance table.
  String get choir => read(json, 'choir', asString);

  /// The window that selected this name, in the terms of its own cycle: an arc of longitude, a span of civil days, or a twenty minute interval of the clock.
  String get window => read(json, 'window', asString);

  /// What the tradition says this name is read for, in the requested language.
  String get reading => read(json, 'reading', asString);
}

/// The birth moment this answer was computed from.
extension type GenerateBirthProfileResponseBirthData.fromJson(
  Map<String, Object?> json
)
    implements Object {
  /// Echo of the birth date.
  String get date => read(json, 'date', asString);

  /// The birth time used, which is noon when none was sent.
  String get time => read(json, 'time', asString);

  /// The timezone resolved to a decimal offset in hours. An IANA name sent on the request is resolved against the birth date, so a summer birth carries its summer offset.
  num get timezone => read(json, 'timezone', asNum);
}

/// The conventions this answer was computed under, echoed so it can be reproduced.
extension type GenerateBirthProfileResponseConventions.fromJson(
  Map<String, Object?> json
)
    implements Object {
  /// Which construction dated the name of the day.
  String get angelDating => read(json, 'angelDating', asString);

  /// Where the civil wheel opened. Reported even under solar-longitude, where it selects nothing, so a stored response records every input.
  String get yearStart => read(json, 'yearStart', asString);

  /// Where 29 February was read as falling.
  String get leapDayPolicy => read(json, 'leapDayPolicy', asString);

  /// Whether the Hebrew date was advanced for nightfall.
  bool get afterSunset => read(json, 'afterSunset', asBool);
}

/// The next Hebrew birthday from targetDate (the current UTC date when omitted), the anniversary of hebrewDate. Three Hebrew dates are missing from some years, and where the anniversary moves to is a matter of community practice rather than arithmetic, so the field is null with a note rather than a guess.
extension type GenerateBirthProfileResponseHebrewBirthday.fromJson(
  Map<String, Object?> json
)
    implements Object {
  /// The Gregorian date of the next Hebrew birthday on or after targetDate, or the current UTC date when targetDate is omitted (that day when it is the birthday), or null when that Hebrew date does not exist in the year it falls in. It is the daytime civil date: the Hebrew day itself opens at nightfall the evening before.
  String? get date => readOrNull(json, 'date', asString);

  /// The Hebrew year of that next anniversary, always later than the birth year. Present on the null branch too, naming the year the date is missing from.
  num get hebrewYear => read(json, 'hebrewYear', asNum);

  /// Present only when the date is null, saying why. Absent otherwise, so a caller can branch on presence.
  String? get note => readOrNull(json, 'note', asString);
}

/// The Hebrew date of the birth.
extension type GenerateBirthProfileResponseHebrewDate.fromJson(
  Map<String, Object?> json
)
    implements Object {
  /// Hebrew year.
  num get year => read(json, 'year', asNum);

  /// Hebrew month name. A leap year carries Adar I and Adar II in place of Adar, which is why the name is returned rather than only a number.
  String get month => read(json, 'month', asString);

  /// Month number in the published algorithm order, Nisan first. Adar II is 13.
  num get monthNumber => read(json, 'monthNumber', asNum);

  /// Day of the Hebrew month, 1 to 30.
  num get day => read(json, 'day', asNum);

  /// True in the seven years of each nineteen that carry a second Adar.
  bool get leapYear => read(json, 'leapYear', asBool);

  /// The date written the way it is printed, with the day and the year in Hebrew letters. Data, identical in every language.
  String get hebrew => read(json, 'hebrew', asString);

  /// Echo of the sunset flag. The Hebrew day begins in the evening, so a moment after nightfall already belongs to the next date and this says whether that was applied.
  bool get afterSunset => read(json, 'afterSunset', asBool);
}

/// The sephirah reached from the value of the Hebrew date written in letters. A numerical convention rather than a classical rule, offered as a way into the tree.
extension type GenerateBirthProfileResponseSephirah.fromJson(
  Map<String, Object?> json
)
    implements Object {
  /// Machine identifier of the sephirah of the birth day.
  String get id => read(json, 'id', asString);

  /// Its position in the emanation, 1 to 10.
  num? get number => readOrNull(json, 'number', asNum);

