    implements Object {
  /// Builds the object to send.
  GenerateDigestRequestBirthData({
    required String date,
    required String time,
    required NumOrString timezone,
    num? latitude,
    num? longitude,
  }) : json = <String, Object?>{
         'date': date,
         'time': time,
         'timezone': timezone,
         'latitude': ?latitude,
         'longitude': ?longitude,
       };
}

/// Per-domain significance multipliers applied before the significance floor and event cap. Bias which domains survive filtering and the cap. Omitted domains default to a weight of 1. Valid keys are western, vedic, and biorhythm.
extension type GenerateDigestRequestDomainWeights.fromJson(
  Map<String, Object?> json
)
    implements Object {
  /// Builds the object to send.
  GenerateDigestRequestDomainWeights({num? western, num? vedic, num? biorhythm})
    : json = <String, Object?>{
        'western': ?western,
        'vedic': ?vedic,
        'biorhythm': ?biorhythm,
      };
}

extension type GenerateDigestResponse.fromJson(Map<String, Object?> json)
    implements Object {
  /// Echo of the birth subject this digest was built for.
  GenerateDigestResponseBirthData get birthData =>
      read(json, 'birthData', model(GenerateDigestResponseBirthData.fromJson));

  /// Start anchor every window is measured from.
  String get startDate => read(json, 'startDate', asString);

  /// Last day of the resolved 90 day horizon the timeline was built over before slicing.
  String get endDate => read(json, 'endDate', asString);

  /// The four rollups in ascending window length: next 24h, 7d, 30d, and 90d from the start anchor.
  List<GenerateDigestResponseWindowsItem> get windows => read(
    json,
    'windows',
    listOf(model(GenerateDigestResponseWindowsItem.fromJson)),
  );
}

/// Echo of the birth subject this digest was built for.
extension type GenerateDigestResponseBirthData.fromJson(
  Map<String, Object?> json
)
    implements Object {
  /// Birth date in YYYY-MM-DD format. Anchors the natal chart and the Vimshottari dasha sequence.
  String get date => read(json, 'date', asString);

  /// Birth time in 24-hour HH:MM:SS format. Precision matters for the natal positions the transit aspects are measured against.
  String get time => read(json, 'time', asString);

  /// Decimal UTC offset the forecast was computed with, resolved from whatever the request sent. An IANA name is resolved to the offset in force at the birth date and time, so this is the literal number applied, never the name.
  num get timezone => read(json, 'timezone', asNum);

  /// Birth latitude in decimal degrees. Optional and does not affect the timeline. Defaults to 0.
  num? get latitude => readOrNull(json, 'latitude', asNum);

  /// Birth longitude in decimal degrees. Optional and does not affect the timeline. Defaults to 0.
  num? get longitude => readOrNull(json, 'longitude', asNum);
}

extension type GenerateDigestResponseWindowsItem.fromJson(
  Map<String, Object?> json
)
    implements Object {
  /// Length of this window in days forward from the start anchor. One of 1, 7, 30, 90.
  num get days => read(json, 'days', asNum);

  /// Inclusive lower bound of the window as an ISO-8601 UTC datetime, the start anchor.
  String get from => read(json, 'from', asString);

  /// Exclusive upper bound of the window as an ISO-8601 UTC datetime, the start anchor plus the window length.
  String get to => read(json, 'to', asString);

  /// Number of events whose datetime falls inside this window.
  num get count => read(json, 'count', asNum);

  /// Count of events in this window broken down by domain. Only domains with at least one event in the window are present. The values sum to count.
  GenerateDigestResponseWindowsItemByDomain get byDomain => read(
    json,
    'byDomain',
    model(GenerateDigestResponseWindowsItemByDomain.fromJson),
  );

  /// Count of events in this window broken down by event type. Only types with at least one event in the window are present. The values sum to count.
  GenerateDigestResponseWindowsItemByType get byType => read(
    json,
    'byType',
    model(GenerateDigestResponseWindowsItemByType.fromJson),
  );

  /// The highest-significance events in this window, most significant first, up to the requested top count. The same TimelineEvent shape as the timeline endpoints.
  List<GenerateDigestResponseWindowsItemTopItem> get top => read(
    json,
    'top',
    listOf(model(GenerateDigestResponseWindowsItemTopItem.fromJson)),
  );
}

/// Count of events in this window broken down by domain. Only domains with at least one event in the window are present. The values sum to count.
