  List<GenerateNameProfileResponseHebrewFormsItem> get hebrewForms => read(
    json,
    'hebrewForms',
    listOf(model(GenerateNameProfileResponseHebrewFormsItem.fromJson)),
  );

  /// `chosen`
  GenerateNameProfileResponseChosen get chosen =>
      read(json, 'chosen', model(GenerateNameProfileResponseChosen.fromJson));

  /// The four readings a name profile leads with. Call the gematria endpoint for the full set and for the substitution transformations.
  GenerateNameProfileResponseValues get values =>
      read(json, 'values', model(GenerateNameProfileResponseValues.fromJson));

  /// The per letter breakdown of the chosen spelling.
  List<GenerateNameProfileResponseLettersItem> get letters => read(
    json,
    'letters',
    listOf(model(GenerateNameProfileResponseLettersItem.fromJson)),
  );

  /// Where the name lands on the tree. The reduction is a numerical convention, not a rule from any text, and the reading says so.
  GenerateNameProfileResponseSephirah get sephirah => read(
    json,
    'sephirah',
    model(GenerateNameProfileResponseSephirah.fromJson),
  );

