  List<GenerateNameProfileResponseMatchesItem> get matches => read(
    json,
    'matches',
    listOf(model(GenerateNameProfileResponseMatchesItem.fromJson)),
  );

  /// `conventions`
  GenerateNameProfileResponseConventions get conventions => read(
    json,
    'conventions',
    model(GenerateNameProfileResponseConventions.fromJson),
  );
}

