extension type GenerateNameProfileResponseHebrewFormsItem.fromJson(
  Map<String, Object?> json
)
    implements Object {
  /// One Hebrew spelling the Latin input can be written as. Data, identical in every language.
  String get hebrew => read(json, 'hebrew', asString);

  /// Latin transcription of the Hebrew beside it, produced by one mechanical letter map. It is a label for reading the string back, never a pronunciation claim.
  String get romanization => read(json, 'romanization', asString);

  /// Why this spelling came out of the map: the parse rule first, then one sentence for every reading the scheme applied that the letters alone would not show, so a caller can tell the parses apart.
  String get rule => read(json, 'rule', asString);

  /// Every computed cipher applied to this spelling, in catalogue order. The rows carry no display name, because they are the same ciphers in the same order for every spelling: read the names off the top level values array once.
  List<GenerateNameProfileResponseHebrewFormsItemValuesItem> get values => read(
    json,
    'values',
    listOf(
      model(GenerateNameProfileResponseHebrewFormsItemValuesItem.fromJson),
    ),
  );

  /// The per letter breakdown of this spelling under the standard reading.
  List<GenerateNameProfileResponseHebrewFormsItemLettersItem> get letters =>
      read(
        json,
        'letters',
        listOf(
          model(GenerateNameProfileResponseHebrewFormsItemLettersItem.fromJson),
        ),
      );
}

