extension type GeneratePlanetaryReturnResponse.fromJson(
  Map<String, Object?> json
)
    implements Object {
  /// Original birth date used for natal planet longitude calculation.
  String get birthDate => read(json, 'birthDate', asString);

  /// Planet whose return was calculated. Each planet has a different orbital period and return significance.
  String get planet => read(json, 'planet', asString);

  /// Exact planetary return moment, when the transiting planet conjuncts its natal longitude. Adjusted to requested timezone. Marks the beginning of a new cycle for that planet in your life.
  String get returnDate => read(json, 'returnDate', asString);

  /// Approximate orbital period for this planet. Mercury ~88 days, Venus ~225 days, Mars ~687 days (~1.9 years), Jupiter ~12 years, Saturn ~29 years.
  String get approximateCycle => read(json, 'approximateCycle', asString);

  /// Location used for the planetary return chart house and Ascendant calculations.
  GeneratePlanetaryReturnResponseLocation get location => read(
    json,
    'location',
    model(GeneratePlanetaryReturnResponseLocation.fromJson),
  );

  /// Full tropical zodiac chart erected for the planetary return moment. Contains planetary positions, house cusps, aspects, Ascendant, and Midheaven.
  GeneratePlanetaryReturnResponseChart get chart =>
      read(json, 'chart', model(GeneratePlanetaryReturnResponseChart.fromJson));

  /// Original natal planet position that defines the return. The transiting planet conjuncts this longitude to trigger the return.
  GeneratePlanetaryReturnResponseNatalPlanetPosition get natalPlanetPosition =>
      read(
        json,
        'natalPlanetPosition',
        model(GeneratePlanetaryReturnResponseNatalPlanetPosition.fromJson),
      );

  /// Planetary return interpretation. Saturn returns (~29 years) mark major life milestones. Jupiter returns (~12 years) signal growth cycles. Inner planet returns offer shorter-term insights.
  GeneratePlanetaryReturnResponseInterpretation get interpretation => read(
    json,
    'interpretation',
    model(GeneratePlanetaryReturnResponseInterpretation.fromJson),
  );
}

/// Full tropical zodiac chart erected for the planetary return moment. Contains planetary positions, house cusps, aspects, Ascendant, and Midheaven.
extension type GeneratePlanetaryReturnResponseChart.fromJson(
  Map<String, Object?> json
)
    implements Object {
  /// Birth details used to generate this chart.
  GeneratePlanetaryReturnResponseChartBirthDetails get birthDetails => read(
    json,
    'birthDetails',
    model(GeneratePlanetaryReturnResponseChartBirthDetails.fromJson),
  );

  /// All 14 celestial bodies in the tropical zodiac with house placements: the 10 classical planets (Sun through Pluto), the lunar nodes (North Node, South Node, in the requested `nodeType` convention), Chiron, and Black Moon Lilith. Chiron is included for charts from 1600 to 2500 and omitted outside that range.
  List<GeneratePlanetaryReturnResponseChartPlanetsItem> get planets => read(
    json,
    'planets',
    listOf(model(GeneratePlanetaryReturnResponseChartPlanetsItem.fromJson)),
  );

  /// All 12 house cusps calculated using the selected house system.
  List<GeneratePlanetaryReturnResponseChartHousesItem> get houses => read(
    json,
    'houses',
    listOf(model(GeneratePlanetaryReturnResponseChartHousesItem.fromJson)),
  );

  /// House system used for this chart (placidus, whole-sign, equal, or koch).
  String get houseSystem => read(json, 'houseSystem', asString);

  /// All planetary aspects found in this chart with orbs, strength, and applying/separating status.
  List<GeneratePlanetaryReturnResponseChartAspectsItem> get aspects => read(
    json,
    'aspects',
    listOf(model(GeneratePlanetaryReturnResponseChartAspectsItem.fromJson)),
  );

  /// Part of Fortune (Lot of Fortune). A point derived from the Ascendant and the two luminaries that marks an area of ease, vitality, and material wellbeing in the chart.
  GeneratePlanetaryReturnResponseChartPartOfFortune get partOfFortune => read(
    json,
    'partOfFortune',
    model(GeneratePlanetaryReturnResponseChartPartOfFortune.fromJson),
  );

  /// Vertex. The western intersection of the prime vertical with the ecliptic, often read as a point of fated encounters and turning-point relationships. The opposite point is the Anti-Vertex.
  GeneratePlanetaryReturnResponseChartVertex get vertex => read(
    json,
    'vertex',
    model(GeneratePlanetaryReturnResponseChartVertex.fromJson),
  );
}

extension type GeneratePlanetaryReturnResponseChartAspectsItem.fromJson(
  Map<String, Object?> json
)
    implements Object {
  /// First planet in the aspect pair.
  String get planet1 => read(json, 'planet1', asString);

  /// Second planet in the aspect pair.
  String get planet2 => read(json, 'planet2', asString);

  /// Aspect type. Major: conjunction (0), opposition (180), trine (120), square (90), sextile (60). Minor: semi-sextile, quincunx, semi-square, sesquiquadrate.
  String get type => read(json, 'type', asString);

  /// Exact angular separation that defines this aspect type in degrees.
  num get angle => read(json, 'angle', asNum);

  /// Deviation from exact aspect in degrees. Tighter orb means stronger influence.
  num get orb => read(json, 'orb', asNum);

  /// Whether the aspect is applying (planets moving toward exact) or separating (moving apart). Applying aspects grow stronger.
  bool get isApplying => read(json, 'isApplying', asBool);

  /// Aspect strength percentage (0-100). Based on orb tightness relative to the allowed maximum.
  num get strength => read(json, 'strength', asNum);

  /// Aspect nature. Harmonious (trine, sextile) flows easily. Challenging (square, opposition) creates tension and growth. Neutral (conjunction) blends energies. Always English, whatever the lang parameter says: it is an identifier consumers switch and style on. Use interpretationLocalized for anything a reader sees.
  String get interpretation => read(json, 'interpretation', asString);
}

