extension type GetAnnualFlyingStarsResponse.fromJson(Map<String, Object?> json)
    implements Object {
  /// The solar year this plate is for.
  num get year => read(json, 'year', asNum);

  /// Flying star number, 1 to 9. The number IS the identifier of the star: 8 is always the Eight White Earth star whichever plate it appears on.
  num get centerStar => read(json, 'centerStar', asNum);

  /// The date this plate takes effect, which is Li Chun and NOT Lunar New Year. Lunar New Year 2026 falls on 17 February, roughly two weeks later, and applying the new plate from that date is the most common error in annual feng shui.
  String get changeoverDate => read(json, 'changeoverDate', asString);

  /// All nine palaces with the star that flew there, centre first and then along the Lo Shu path. The plate is universal: it is the same for every building on earth.
  List<GetAnnualFlyingStarsResponsePalacesItem> get palaces => read(
    json,
    'palaces',
    listOf(model(GetAnnualFlyingStarsResponsePalacesItem.fromJson)),
  );
}

extension type GetAnnualFlyingStarsResponsePalacesItem.fromJson(
  Map<String, Object?> json
)
    implements Object {
  /// Palace of the Lo Shu grid: one of the eight compass sectors, or Center. Always English, safe to compare against and to key a grid cell on.
  String get palace => read(json, 'palace', asString);

  /// Flying star number, 1 to 9. The number IS the identifier of the star: 8 is always the Eight White Earth star whichever plate it appears on.
  num get star => read(json, 'star', asNum);

  /// Display name of the star in this palace. Always English, whatever the lang parameter says. Use nameLocalized for anything a reader sees.
  String get name => read(json, 'name', asString);

  /// Star name in the requested language, for display only. Present only when lang is set to a language other than English.
  String? get nameLocalized => readOrNull(json, 'nameLocalized', asString);

  /// Five phase of this entry: Wood, Fire, Earth, Metal or Water. Always English so it stays safe to compare against and to key styling on. The full cycles live on the Chinese astrology elements endpoint.
  String get element => read(json, 'element', asString);

  /// The untimely reading of the star, auspicious or inauspicious.
  String get nature => read(json, 'nature', asString);

  /// Five phase of this entry: Wood, Fire, Earth, Metal or Water. Always English so it stays safe to compare against and to key styling on. The full cycles live on the Chinese astrology elements endpoint.
  String get enhancer => read(json, 'enhancer', asString);

  /// Five phase of this entry: Wood, Fire, Earth, Metal or Water. Always English so it stays safe to compare against and to key styling on. The full cycles live on the Chinese astrology elements endpoint.
  String get remedy => read(json, 'remedy', asString);

  /// What the star does in the sector it has flown to this period.
  String get meaning => read(json, 'meaning', asString);
}

extension type GetAvasthaResponse.fromJson(Map<String, Object?> json)
    implements Object {
  /// Unique slug for the avastha state. It is the lowercased form of the state name the birth chart returns, so a chart value maps straight onto this record.
  String get id => read(json, 'id', asString);

  /// Sanskrit name of the state, exactly as it appears in the `awastha`, `jagradadi` or `deeptadi` field of a birth chart.
  String get name => read(json, 'name', asString);

  /// Which avastha system the state belongs to, and therefore which birth-chart field it appears in. "baladi" is the five-fold age state set by degree within the sign and appears in `awastha`. "jagradadi" is the three-fold waking state set by sign dignity. "deeptadi" is the nine-fold dispositional state. Baladi applies to every body; the other two apply to the seven classical grahas only.
  String get system => read(json, 'system', asString);

  /// Short label for the state, sized for a table cell beside the graha.
  String get meaning => read(json, 'meaning', asString);

  /// What the state means for the results the graha delivers, which is the whole purpose of reading an avastha: the chart says where a graha is, the avastha says how much of its promise it can keep.
  String get interpretation => read(json, 'interpretation', asString);
}

extension type GetAztecDaySignResponse.fromJson(Map<String, Object?> json)
    implements Object {
  /// Place in the twenty sign sequence, 1 to 20, counting Cipactli as 1. The sequence never varies and is what the trecenas are indexed against.
  num get position => read(json, 'position', asNum);

  /// Machine identifier of the day sign, always lowercase ASCII Nahuatl whatever the lang parameter says, so it stays safe to compare against and to use as a path parameter. The twenty ids run cipactli, ehecatl, calli, cuetzpalin, coatl, miquiztli, mazatl, tochtli, atl, itzcuintli, ozomahtli, malinalli, acatl, ocelotl, cuauhtli, cozcacuauhtli, ollin, tecpatl, quiahuitl, xochitl.
  String get id => read(json, 'id', asString);

  /// Display name in Nahuatl with the vowel length marks the reference tables print. A proper noun carried as data, identical under every lang.
  String get nameNahuatl => read(json, 'nameNahuatl', asString);

  /// What the sign name means, translated in place because it is a common noun. Where several English renderings are in circulation all of them are given rather than one being picked.
  String get gloss => read(json, 'gloss', asString);

  /// World direction the sign belongs to: east, north, west or south. The twenty run through the four quarters in strict rotation, so every fourth sign shares a quarter.
  String get direction => read(json, 'direction', asString);

  /// What the sign is about, as a clause rather than a sentence, because it is spliced into composed prose elsewhere in the API. Translated in place.
  String get essence => read(json, 'essence', asString);

  /// The one thing worth doing differently under this sign.
  String get guidance => read(json, 'guidance', asString);

  /// The sign in one composed sentence, built from the components above.
  String get keynote => read(json, 'keynote', asString);
}

extension type GetAztecTrecenaResponse.fromJson(Map<String, Object?> json)
    implements Object {
  /// Which of the twenty thirteen day periods this is, 1 to 20. Trecena 1 opens on 1 Cipactli and the openers step thirteen signs at a time from there.
  num get number => read(json, 'number', asNum);

  /// Machine identifier of the day sign the period opens on.
  String get startSign => read(json, 'startSign', asString);

  /// Display name of the sign the period opens on. A proper noun carried as data.
  String get startSignName => read(json, 'startSignName', asString);

  /// Days in the period. Always 13, which is what the word trecena means.
  num get length => read(json, 'length', asNum);

  /// The composed reading of the period, built from the sign it opens on rather than stored, so the two can never drift apart. No patron deity is named, because two of the twenty published patrons are disputed and none ships rather than eighteen shipping beside two guesses.
  String get reading => read(json, 'reading', asString);
}

extension type GetBaguaSectorResponse.fromJson(Map<String, Object?> json)
    implements Object {
  /// Life area id: career, knowledge, family, wealth, fame, love, children, helpful-people or health. Always English, whatever the lang parameter says, so it stays safe to compare against in code. Use nameLocalized for anything a reader sees.
  String get id => read(json, 'id', asString);

  /// Display name of the life area. Always English, whatever the lang parameter says. Use nameLocalized for anything a reader sees.
  String get name => read(json, 'name', asString);

  /// Life area name in the requested language, for display only. Present only when lang is set to a language other than English, since in English it would repeat name exactly. Never compare against this value.
  String? get nameLocalized => readOrNull(json, 'nameLocalized', asString);

  /// Lo Shu number of the palace, 1 to 9. This is the same number the flying stars use, so a chart palace and a Bagua sector line up by it.
  num get number => read(json, 'number', asNum);

  /// Palace of the Lo Shu grid: one of the eight compass sectors, or Center for the ninth. Always English, safe to compare against.
  String get palace => read(json, 'palace', asString);

  /// Compass sector of the palace, taken from the trigram that sits there. Absent on the centre palace, which has no direction.
  String? get direction => readOrNull(json, 'direction', asString);

  /// Five phase of this entry: Wood, Fire, Earth, Metal or Water. Always English so it stays safe to compare against and to key styling on. The full cycles live on the Chinese astrology elements endpoint.
  String get element => read(json, 'element', asString);

  /// Colours of the phase this sector carries, for activating it. Derived from the element rather than assigned per sector, so they cannot disagree with the element beside them.
  List<String> get colors => read(json, 'colors', listOf(asString));

  /// The Later Heaven trigram of the sector, which is the arrangement every compass reading and every flying star chart uses. Absent on the centre palace.
  GetBaguaSectorResponseTrigram? get trigram => readOrNull(
    json,
    'trigram',
    model(GetBaguaSectorResponseTrigram.fromJson),
  );

  /// The trigram that sits in this direction under the Earlier Heaven arrangement, read for the symbolic relation between opposite sectors. A different question from the Later Heaven trigram, not a competing answer. Absent on the centre palace.
  GetBaguaSectorResponseEarlierHeavenTrigram? get earlierHeavenTrigram =>
      readOrNull(
        json,
        'earlierHeavenTrigram',
        model(GetBaguaSectorResponseEarlierHeavenTrigram.fromJson),
      );

  /// What this sector governs, in a few words.
  String get focus => read(json, 'focus', asString);

  /// What the sector governs and how to work with it.
  String get meaning => read(json, 'meaning', asString);
}

