  GetCurrentDashaResponsePranaDashaSignificators? get significators =>
      readOrNull(
        json,
        'significators',
        model(GetCurrentDashaResponsePranaDashaSignificators.fromJson),
      );

  /// Parent Mahadasha lord under which this Antardasha sub-period runs.
  String get mahadashaLord => read(json, 'mahadashaLord', asString);

  /// Parent Antardasha lord under which this Pratyantardasha runs.
  String get antardashaLord => read(json, 'antardashaLord', asString);

  /// Parent Pratyantardasha lord under which this Sookshma dasha runs.
  String get pratyantardashaLord => read(json, 'pratyantardashaLord', asString);

  /// Parent Sookshma dasha lord under which this Prana dasha runs.
