  GetDailyAyurvedaReadingResponseBrahmaMuhurta get brahmaMuhurta => read(
    json,
    'brahmaMuhurta',
    model(GetDailyAyurvedaReadingResponseBrahmaMuhurta.fromJson),
  );

  /// The six blocks, cut from the actual day and night at this place into thirds.
  List<GetDailyAyurvedaReadingResponseDoshaPeriodsItem> get doshaPeriods =>
      read(
        json,
        'doshaPeriods',
        listOf(model(GetDailyAyurvedaReadingResponseDoshaPeriodsItem.fromJson)),
