extension type GetDinacharyaScheduleResponse.fromJson(Map<String, Object?> json)
    implements Object {
  /// The local date this schedule is for, echoing the request.
  String get date => read(json, 'date', asString);

  /// Sunrise at this place on this date, as an ISO 8601 instant in UTC. The day begins here, which is why every block below is measured from it rather than from midnight.
  String get sunrise => read(json, 'sunrise', asString);

  /// Sunset at this place on this date, as an ISO 8601 instant in UTC.
  String get sunset => read(json, 'sunset', asString);

  /// The following sunrise, as an ISO 8601 instant in UTC. It closes the night, so the three night blocks are cut between this and the sunset above.
  String get nextSunrise => read(json, 'nextSunrise', asString);

  /// The pre-dawn window, as a fixed offset from sunrise. It is not scaled to the length of the night, and calculators that scale it are following a reading the commentary rejects.
  GetDinacharyaScheduleResponseBrahmaMuhurta get brahmaMuhurta => read(
    json,
    'brahmaMuhurta',
    model(GetDinacharyaScheduleResponseBrahmaMuhurta.fromJson),
  );

  /// The six blocks under the convention that was requested, in chronological order.
  List<GetDinacharyaScheduleResponseDoshaPeriodsItem> get doshaPeriods => read(
    json,
    'doshaPeriods',
    listOf(model(GetDinacharyaScheduleResponseDoshaPeriodsItem.fromJson)),
  );

  /// The same six blocks under the other convention, so a caller can show one and reconcile against the other without a second call.
  List<GetDinacharyaScheduleResponseAlternatePeriodsItem>
  get alternatePeriods => read(
    json,
    'alternatePeriods',
    listOf(model(GetDinacharyaScheduleResponseAlternatePeriodsItem.fromJson)),
  );

  /// The daily sequence the chapter gives, in its own order.
  List<GetDinacharyaScheduleResponseRoutineItem> get routine => read(
    json,
    'routine',
    listOf(model(GetDinacharyaScheduleResponseRoutineItem.fromJson)),
  );

  /// The day in prose, composed and translated in place.
  String get summary => read(json, 'summary', asString);

  /// Every work behind this response, once each.
  List<GetDinacharyaScheduleResponseSourcesItem> get sources => read(
    json,
    'sources',
    listOf(model(GetDinacharyaScheduleResponseSourcesItem.fromJson)),
  );

  /// The conventions this schedule was produced under.
  GetDinacharyaScheduleResponseConventions get conventions => read(
    json,
    'conventions',
    model(GetDinacharyaScheduleResponseConventions.fromJson),
  );

  /// Scope of the response.
  GetDinacharyaScheduleResponseMeta get meta =>
      read(json, 'meta', model(GetDinacharyaScheduleResponseMeta.fromJson));
}

