  String get dosha => read(json, 'dosha', asString);

  /// When the block opens, as an ISO 8601 instant in UTC.
  String get start => read(json, 'start', asString);

  /// When the block closes, as an ISO 8601 instant in UTC.
  String get end => read(json, 'end', asString);

