  /// Zodiac sign this planet rules (domicile). Where the planet operates most naturally. Absent for the lunar nodes, Chiron, and Black Moon Lilith.
  String? get rulership => readOrNull(json, 'rulership', asString);

  /// Sign of detriment. Opposite the rulership sign, where the planet struggles. Absent for the lunar nodes, Chiron, and Black Moon Lilith.
  String? get detriment => readOrNull(json, 'detriment', asString);

  /// Sign of exaltation. Where the planet is honored and amplified. Absent for the lunar nodes, Chiron, and Black Moon Lilith.
  String? get exaltation => readOrNull(json, 'exaltation', asString);

  /// Deprecated: use exaltation. Retained for backward compatibility, scheduled for removal in v3. Sign of exaltation, carrying the same value as the exaltation field.
  String? get exultation => readOrNull(json, 'exultation', asString);

  /// Sign of fall. Opposite the exaltation sign, where the planet is weakened. Absent for the lunar nodes, Chiron, and Black Moon Lilith.
  String? get fall => readOrNull(json, 'fall', asString);

  /// Positive and negative keyword associations for this planet.
  GetPlanetMeaningResponseKeywords get keywords =>
      read(json, 'keywords', model(GetPlanetMeaningResponseKeywords.fromJson));

  /// Planet description in short and long form.
  GetPlanetMeaningResponseDescription get description => read(
    json,
    'description',
    model(GetPlanetMeaningResponseDescription.fromJson),
  );
}

