  String get sign => read(json, 'sign', asString);

  /// Degree within the zodiac sign (0-29.999).
  num get degree => read(json, 'degree', asNum);

  /// Daily motion in degrees per day. Negative values indicate retrograde.
  num get speed => read(json, 'speed', asNum);

  /// Whether the planet is in apparent retrograde motion.
  bool get isRetrograde => read(json, 'isRetrograde', asBool);

  /// Unicode astronomical symbol for this planet.
  String? get symbol => readOrNull(json, 'symbol', asString);

  /// Short tagline summarizing what this planet governs.
  String? get tagline => readOrNull(json, 'tagline', asString);

  /// Brief description of this planet in astrological context.
  String? get description => readOrNull(json, 'description', asString);

  /// Key themes and traits associated with this planet.
  List<String>? get keywords => readOrNull(json, 'keywords', listOf(asString));

  /// Planet-in-sign interpretation. How this planet expresses through the zodiac sign it currently occupies.
  GetPlanetaryPositionsResponsePlanetsItemInterpretation? get interpretation =>
      readOrNull(
        json,
        'interpretation',
        model(GetPlanetaryPositionsResponsePlanetsItemInterpretation.fromJson),
      );
}

