extension type GetReadingResponse.fromJson(Map<String, Object?> json)
    implements Object {
  /// Birth date used for this calculation (YYYY-MM-DD).
  String get birthDate => read(json, 'birthDate', asString);

  /// Date this reading is for (YYYY-MM-DD).
  String get targetDate => read(json, 'targetDate', asString);

  /// Total days alive from birth date to target date. This is the basis for all cycle calculations.
  num get daysSinceBirth => read(json, 'daysSinceBirth', asNum);

  /// All 10 biorhythm cycle readings. Keys: physical, emotional, intellectual, intuitive, aesthetic, awareness, spiritual, passion, mastery, wisdom.
  Map<String, GetReadingResponseCyclesValue> get cycles => read(
    json,
    'cycles',
    mapOf(model(GetReadingResponseCyclesValue.fromJson)),
  );

  /// Overall energy score from 1 (deep recovery) to 10 (peak performance), derived from the three primary cycle positions.
  num get energyRating => read(json, 'energyRating', asNum);

  /// Summary phase across every cycle for the day. One of: high_energy, mixed, recovery, critical.
  String get overallPhase => read(json, 'overallPhase', asString);

  /// Editorial 3-5 sentence reading combining all cycle states into a coherent daily assessment.
  String get interpretation => read(json, 'interpretation', asString);

  /// Actionable 1-2 sentence guidance for the day based on the combined cycle analysis.
  String get advice => read(json, 'advice', asString);

  /// Critical day alerts. Present only when one or more primary cycles are at or near zero crossing.
  List<GetReadingResponseCriticalAlertsItem> get criticalAlerts => read(
    json,
    'criticalAlerts',
    listOf(model(GetReadingResponseCriticalAlertsItem.fromJson)),
  );
}

extension type GetReadingResponseCriticalAlertsItem.fromJson(
  Map<String, Object?> json
)
    implements Object {
  /// Which cycle is at or near zero crossing.
  String get cycle => read(json, 'cycle', asString);

  /// Alert type. One of: zero_crossing. Raised once for the whole critical band, when the cycle sits within 9 points of zero in either direction.
  String get type => read(json, 'type', asString);

  /// Whether the cycle is rising through zero (ascending) or falling through zero (descending).
  String get direction => read(json, 'direction', asString);

  /// Specific advisory text for this critical alert.
  String get advisory => read(json, 'advisory', asString);
}

/// One cycle read for the target date: its position and raw sine value, phase and trend, day within the period, the distance to the next peak, trough and critical day, and a short reading.
extension type GetReadingResponseCyclesValue.fromJson(Map<String, Object?> json)
    implements Object {
  /// Percentage position in the cycle from -100 (trough) to 100 (peak). 0 represents a critical zero crossing.
  num get value => read(json, 'value', asNum);

  /// Raw sine wave value before percentage conversion, ranging from -1.0 to 1.0.
  num get rawValue => read(json, 'rawValue', asNum);

  /// Current phase of the cycle. One of: peak, high, rising, critical_ascending, critical_descending, falling, low, trough. Canonical English whatever the lang parameter says, so it stays safe to compare against in code; phaseLabel carries the reader-facing form and IS translated.
  String get phase => read(json, 'phase', asString);

  /// Human-readable phase name for display in UIs, dashboards, and reports.
  String get phaseLabel => read(json, 'phaseLabel', asString);

  /// Current day position within the cycle (1-based). Ranges from 1 to the cycle period length.
  num get dayInCycle => read(json, 'dayInCycle', asNum);

  /// Number of days until the next peak (100%) in this cycle.
  num get daysUntilPeak => read(json, 'daysUntilPeak', asNum);

  /// Number of days until the next trough (-100%) in this cycle.
  num get daysUntilTrough => read(json, 'daysUntilTrough', asNum);

  /// Number of days until the next zero crossing in this cycle.
  num get daysUntilCritical => read(json, 'daysUntilCritical', asNum);

  /// Short-term direction of the cycle, which is its SLOPE rather than its band, so it moves independently of phase. One of: rising, falling, peaking, bottoming. Canonical English, like phase.
  String get trend => read(json, 'trend', asString);

  /// Editorial 2-3 sentence reading specific to this cycle at its current phase position.
  String get interpretation => read(json, 'interpretation', asString);
}

extension type GetRitucharyaResponse.fromJson(Map<String, Object?> json)
    implements Object {
  /// The date this reading is for, echoing the request.
  String get date => read(json, 'date', asString);

  /// The season in force on this date.
  GetRitucharyaResponseRitu get ritu =>
