extension type KPCuspsResponse.fromJson(Map<String, Object?> json)
    implements Object {
  /// Applied ayanamsa value in degrees
  num get ayanamsa => read(json, 'ayanamsa', asNum);

  /// House system used for calculations
  String get houseSystem => read(json, 'houseSystem', asString);

  /// `cusps`
  List<KPCuspsResponseCuspsItem> get cusps =>
      read(json, 'cusps', listOf(model(KPCuspsResponseCuspsItem.fromJson)));

  /// Significations of each of the twelve bhavas (houses), keyed by house number 1 to 12, as short keywords. Bhava 1 is the Lagna (self, body, vitality), 2 wealth and speech, 4 home and mother, 7 marriage and partnership, 10 career and status, 11 gains. Use it to label the house numbers returned elsewhere in the response: a Vimshottari dasha period signifying houses 2, 7 and 8, or a KP significator carrying houses 11 and 6, becomes readable text without a separate lookup call. Returned once per response rather than repeated per period, and localized by the lang query parameter alongside every other interpretation field.
  Map<String, List<String>> get houseThemes =>
      read(json, 'houseThemes', mapOf(listOf(asString)));

  /// Which signification vocabulary produced the houseThemes keywords in this response, echoing the focus query parameter. Always present, and "general" when the parameter was omitted. Read it to label a rendered house legend, or to tell two cached responses apart when only one asked for the finance lens.
  String get focus => read(json, 'focus', asString);
}

extension type KPCuspsResponseCuspsItem.fromJson(Map<String, Object?> json)
    implements Object {
  /// House number (1-12)
  num get house => read(json, 'house', asNum);

  /// Cusp longitude in degrees (0-360)
  num get longitude => read(json, 'longitude', asNum);

  /// Zodiac sign of the cusp
  String get sign => read(json, 'sign', asString);

  /// Rashi lord (sign ruler) of this cusp. In KP, the cusp sign lord is a significator for this house.
  String get signLord => read(json, 'signLord', asString);

  /// Nakshatra (lunar mansion) at this cusp degree. The cusp nakshatra lord and sublord together determine the houses complete significator chain.
  String get nakshatra => read(json, 'nakshatra', asString);

  /// Nakshatra lord (star ruler) of the cusp. One of 9 Vimshottari dasha lords. Determines which planet activates this cusp in KP predictions.
  String get nakshatraLord => read(json, 'nakshatraLord', asString);

  /// Nakshatra pada/quarter (1-4)
  num get pada => read(json, 'pada', asNum);

  /// Star-lord (nakshatra lord)
  String get starLord => read(json, 'starLord', asString);

  /// Sub-lord based on KP 249-level subdivision
  String get subLord => read(json, 'subLord', asString);

  /// Sub-sub lord (SSL) based on 2241-level KP subdivision. Third level of Vimshottari dasha proportions.
  String get subSubLord => read(json, 'subSubLord', asString);

  /// KP horary number (1-249)
  num get kpNumber => read(json, 'kpNumber', asNum);
}

/// Layer weights in percent, all four required, summing to 100. Defaults to the convention, cusps 30, dasha 40, rulingPlanets 15, moonWindows 15. Seventy percent of the default sits on the cusps and the outer dasha levels, which hold for months, so a chart reads inside a narrow band all month and the bands separate charts more than days. Move weight onto rulingPlanets and moonWindows for a reading that turns with the day.
extension type KPDailyFinanceRequestWeights.fromJson(Map<String, Object?> json)
    implements Object {
  /// Builds the object to send.
  KPDailyFinanceRequestWeights({
    required num cusps,
    required num dasha,
    required num rulingPlanets,
    required num moonWindows,
  }) : json = <String, Object?>{
         'cusps': cusps,
         'dasha': dasha,
         'rulingPlanets': rulingPlanets,
         'moonWindows': moonWindows,
       };
}

extension type KPDailyFinanceResponse.fromJson(Map<String, Object?> json)
    implements Object {
  /// The civil date read.
  String get date => read(json, 'date', asString);

  /// The reading moment, local datetime in the request timezone. The ruling planets and the dasha lords are read here.
  String get readingAt => read(json, 'readingAt', asString);

  /// Ayanamsa system for sidereal conversion. "kp-newcomb" uses the KP-Newcomb dynamic formula, the most common choice for KP astrology. "kp-old" uses the Krishnamurti original table from KP Reader-1 with constant precession rate. "lahiri" uses Lahiri/Chitrapaksha ayanamsa, matching most traditional Vedic software. "raman" uses the B.V. Raman ayanamsa from Hindu Predictive Astrology, a recognised traditional school that sits about 1.45 degrees below Lahiri. Defaults to "kp-newcomb".
  String? get ayanamsa => readOrNull(json, 'ayanamsa', asString);

  /// Degrees subtracted from the tropical longitudes, resolved at the birth date. One frame for the whole reading: cusps, significators, Vimshottari balance, ruling planets and Moon windows alike.
  num get ayanamsaDegrees => read(json, 'ayanamsaDegrees', asNum);

  /// `houses`
  KPDailyFinanceResponseHouses get houses =>
      read(json, 'houses', model(KPDailyFinanceResponseHouses.fromJson));

  /// `significators`
  KPDailyFinanceResponseSignificators get significators => read(
    json,
    'significators',
    model(KPDailyFinanceResponseSignificators.fromJson),
  );

  /// `layers`
  KPDailyFinanceResponseLayers get layers =>
      read(json, 'layers', model(KPDailyFinanceResponseLayers.fromJson));

  /// The weight-sum of the four layer scores, 0 to 100, one decimal: cusps 30, dasha 40, rulingPlanets 15, moonWindows 15, each divided by 100. Recomputable from the layers printed above. The house groups, the classification, the inversion on the loss cusps, the retrograde penalty, the level weights and the layer weights are a KP practitioner convention adopted as the published convention of this route: no classical KP text weighs these four layers against each other, and every table behind the number is printed so the result can be checked line by line rather than trusted. The score measures what the method outputs for the day, never the probability of a gain or a loss.
  num get score => read(json, 'score', asNum);

  /// The score as one of five bands, each entered at its edge: "strong" from 70, "favourable" from 55, "mixed" from 45, "caution" from 30, "unfavourable" below 30. "mixed" is the ordinary day. Canonical English machine values.
  String get band => read(json, 'band', asString);

  /// The favourable Moon window of the day, the longest when several qualify, or null when the day has none. The one stretch the method backs outright.
  KPDailyFinanceResponseBestWindow? get bestWindow => readOrNull(
    json,
    'bestWindow',
    model(KPDailyFinanceResponseBestWindow.fromJson),
  );

  /// Every unfavourable Moon window of the day, in clock order.
  List<KPDailyFinanceResponseWorstWindowsItem> get worstWindows => read(
    json,
    'worstWindows',
    listOf(model(KPDailyFinanceResponseWorstWindowsItem.fromJson)),
  );
}

/// The favourable Moon window of the day, the longest when several qualify, or null when the day has none. The one stretch the method backs outright.
extension type KPDailyFinanceResponseBestWindow.fromJson(
  Map<String, Object?> json
)
    implements Object {
  /// Whether the planet signifies at least one gain house at any of the four tiers.
  bool get inGain => read(json, 'inGain', asBool);

  /// Whether the planet signifies at least one loss house at any of the four tiers.
  bool get inLoss => read(json, 'inLoss', asBool);

  /// The one classification every layer uses: "favourable" when the planet signifies a gain house and no loss house (100), "mixed" when it signifies both (50), "unfavourable" when it signifies a loss house and no gain house (0), "neutral" when it signifies neither (50). Canonical English machine value.
  String get verdict => read(json, 'verdict', asString);

  /// Local datetime the window opens, in the request timezone.
  String get from => read(json, 'from', asString);

  /// Local datetime the window closes. The last window of the day closes at the next midnight.
  String get to => read(json, 'to', asString);

  /// The KP sub lord the Moon holds through this window, the planet the row classifies.
  String get subLord => read(json, 'subLord', asString);

  /// The verdict score of the window.
  num get score => read(json, 'score', asNum);
}

