extension type NatalChartResponse.fromJson(Map<String, Object?> json)
    implements Object {
  /// Birth details echoed back from the request. Confirms the input used for this chart calculation.
  NatalChartResponseBirthDetails get birthDetails => read(
    json,
    'birthDetails',
    model(NatalChartResponseBirthDetails.fromJson),
  );

  /// All 14 celestial bodies (10 classical planets, lunar nodes, Chiron, Black Moon Lilith) with zodiac signs, house placements, and interpretations.
  List<NatalChartResponsePlanetsItem> get planets => read(
    json,
    'planets',
    listOf(model(NatalChartResponsePlanetsItem.fromJson)),
  );

  /// All 12 house cusps with zodiac positions. House cusps divide the chart into life areas.
  List<NatalChartResponseHousesItem> get houses => read(
    json,
    'houses',
    listOf(model(NatalChartResponseHousesItem.fromJson)),
  );

  /// House system used for this chart (placidus, whole-sign, equal, or koch).
  String get houseSystem => read(json, 'houseSystem', asString);

  /// All planetary aspects found in this chart with orbs, strength, and interpretation.
  List<NatalChartResponseAspectsItem> get aspects => read(
    json,
    'aspects',
    listOf(model(NatalChartResponseAspectsItem.fromJson)),
  );

  /// Detected multi-planet aspect configurations (Grand Trine, Kite, T-Square, Grand Cross, Yod, Mystic Rectangle, Stellium). Grand Cross suppresses contained T-Squares, Kite suppresses underlying Grand Trine.
  List<NatalChartResponsePatternsItem>? get patterns => readOrNull(
    json,
    'patterns',
    listOf(model(NatalChartResponsePatternsItem.fromJson)),
  );

  /// Aspect pattern analysis showing the balance of harmonious vs challenging energies in the chart.
  NatalChartResponseAspectsInterpretation get aspectsInterpretation => read(
    json,
    'aspectsInterpretation',
    model(NatalChartResponseAspectsInterpretation.fromJson),
  );

  /// Ascendant (rising sign). The eastern horizon at birth, defining outward personality and physical appearance.
  NatalChartResponseAscendant get ascendant =>
      read(json, 'ascendant', model(NatalChartResponseAscendant.fromJson));

  /// Midheaven (MC). The highest point of the ecliptic at birth, representing career direction and public image.
  NatalChartResponseMidheaven get midheaven =>
      read(json, 'midheaven', model(NatalChartResponseMidheaven.fromJson));

  /// Part of Fortune (Lot of Fortune). A point derived from the Ascendant and the two luminaries that marks an area of ease, vitality, and material wellbeing in the chart.
  NatalChartResponsePartOfFortune get partOfFortune => read(
    json,
    'partOfFortune',
    model(NatalChartResponsePartOfFortune.fromJson),
  );

  /// Vertex. The western intersection of the prime vertical with the ecliptic, often read as a point of fated encounters and turning-point relationships. The opposite point is the Anti-Vertex.
  NatalChartResponseVertex get vertex =>
      read(json, 'vertex', model(NatalChartResponseVertex.fromJson));

  /// Chart summary with dominant element, modality, retrograde planets, and distribution analysis.
  NatalChartResponseSummary get summary =>
      read(json, 'summary', model(NatalChartResponseSummary.fromJson));
}

