extension type TransitsResponseTransitPlanetsItem.fromJson(
  Map<String, Object?> json
)
    implements Object {
  /// Planet name (Sun, Moon, Mercury, Venus, Mars, Jupiter, Saturn, Uranus, Neptune, Pluto, North Node, South Node, Chiron, Black Moon Lilith). Always English, whatever the lang parameter says, so it stays safe to compare against in code. Use nameLocalized for anything a reader sees. The lunar nodes follow the request nodeType, which defaults to the true (osculating) node; pass "mean" for the smoothed node. The two differ by up to about 1.8 degrees and no other body is affected. Black Moon Lilith is always the mean lunar apogee, whatever nodeType says. POST /lilith returns the mean and the true (osculating) apogee side by side, each labelled by its variant.
  String get name => read(json, 'name', asString);

  /// Planet name in the requested language, for display only. Present only when lang is set to a language other than English, since in English it would repeat its canonical partner field exactly. Never compare against this value, compare against the canonical field beside it.
  String? get nameLocalized => readOrNull(json, 'nameLocalized', asString);

  /// Apparent geocentric tropical longitude on the true ecliptic of date, in degrees (0-360): light time and aberration applied, nutation included, the convention desktop chart software and the NASA JPL Horizons observer tables print, so it compares directly with either. Primary coordinate for sign and aspect calculation.
  num get longitude => read(json, 'longitude', asNum);

  /// Apparent geocentric ecliptic latitude of date, in degrees. Near zero for most planets except Moon and Pluto.
  num get latitude => read(json, 'latitude', asNum);

  /// Tropical zodiac sign the planet currently occupies. Changes when longitude crosses a 30-degree boundary. Always English, whatever the lang parameter says. Use signLocalized for anything a reader sees.
  String get sign => read(json, 'sign', asString);

  /// Zodiac sign name in the requested language, for display only. Present only when lang is set to a language other than English, since in English it would repeat its canonical partner field exactly. Never compare against this value, compare against the canonical field beside it.
  String? get signLocalized => readOrNull(json, 'signLocalized', asString);

  /// Degree within the current zodiac sign (0-29.999). Indicates how far into the sign the planet has progressed.
  num get degree => read(json, 'degree', asNum);

  /// Daily motion in degrees per day. Negative values indicate retrograde motion.
  num get speed => read(json, 'speed', asNum);

  /// Whether the planet is currently in apparent retrograde motion. Retrograde transits are considered more introspective and revisionary.
  bool get isRetrograde => read(json, 'isRetrograde', asBool);
}

extension type Trigram.fromJson(Map<String, Object?> json) implements Object {
  /// Stable identifier for the trigram, 1 to 8. This is our lookup key, not a canonical sequence: the tradition has several orderings (King Wen, Fu Xi, Earlier and Later Heaven) and they disagree, so do not read ranking or precedence into it.
  num get number => read(json, 'number', asNum);

  /// Unicode trigram symbol (three lines) for visual display in I-Ching interfaces and Bagua diagrams.
  String get symbol => read(json, 'symbol', asString);

  /// Original Chinese character name of the trigram in traditional script.
  String get chinese => read(json, 'chinese', asString);

  /// English name representing the natural force or element this trigram embodies.
  String get english => read(json, 'english', asString);

  /// Pinyin romanization of the Chinese name with tone marks for correct pronunciation.
  String get pinyin => read(json, 'pinyin', asString);

  /// Three-digit binary representation of the trigram lines (bottom to top). 1 = yang (solid), 0 = yin (broken).
  String get binary => read(json, 'binary', asString);

  /// Five element (Wu Xing) correspondence: Metal, Wood, Water, Fire, or Earth. Used in Chinese metaphysics and feng shui analysis.
  String get element => read(json, 'element', asString);

  /// Core attribute or quality this trigram represents in I-Ching philosophy (e.g., Creative, Receptive, Arousing).
  String get attribute => read(json, 'attribute', asString);

  /// Family archetype in the Bagua system. Each trigram corresponds to a family role (Father, Mother, First Son, First Daughter, etc.).
  String get familyMember => read(json, 'familyMember', asString);

  /// Compass direction in the King Wen (Later Heaven) Bagua arrangement. Used in feng shui spatial analysis.
  String get direction => read(json, 'direction', asString);

  /// Body part associated with this trigram in traditional Chinese medicine and I-Ching body mapping.
  String get bodyPart => read(json, 'bodyPart', asString);

  /// Animal symbol associated with this trigram in classical I-Ching imagery and divination.
  String get animal => read(json, 'animal', asString);

  /// Season or time period associated with this trigram in the annual cycle of Chinese cosmology.
  String get season => read(json, 'season', asString);

  /// Energetic quality describing the dynamic nature of this trigram (e.g., Strong, Devoted, Joyous, Gentle).
  String get quality => read(json, 'quality', asString);

  /// Concise interpretation of the trigram covering its symbolic meaning, key associations, and guidance for understanding hexagrams containing this trigram.
  String get meaning => read(json, 'meaning', asString);
}

/// Complete upagraha positions for a birth chart
extension type UpagrahaResponse.fromJson(Map<String, Object?> json)
    implements Object {
  /// The sidereal frame this response was computed in, so a cached or forwarded payload is self describing.
  UpagrahaResponseFrame get frame =>
      read(json, 'frame', model(UpagrahaResponseFrame.fromJson));

  /// Time-based upagrahas derived from the 8-part division of day or night. Gulika and Mandi are from Saturn segment, others from Sun, Mars, Mercury, Jupiter segments. Positions depend on birth time, location, and weekday.
  List<UpagrahaResponseTimeBasedItem> get timeBased => read(
    json,
    'timeBased',
    listOf(model(UpagrahaResponseTimeBasedItem.fromJson)),
  );

  /// Sun-longitude-based upagrahas (Dhuma group). Pure arithmetic from the Sun sidereal position. Dhuma = Sun + 133d20m, then each derived from the previous.
  List<UpagrahaResponseSunBasedItem> get sunBased => read(
    json,
    'sunBased',
    listOf(model(UpagrahaResponseSunBasedItem.fromJson)),
  );
}

/// The sidereal frame this response was computed in, so a cached or forwarded payload is self describing.
extension type UpagrahaResponseFrame.fromJson(Map<String, Object?> json)
    implements Object {
  /// Sidereal frame this chart was cast in, echoing the ayanamsa request field. "lahiri" when the field was omitted.
  String get ayanamsa => read(json, 'ayanamsa', asString);

  /// Degrees actually subtracted from every tropical longitude to produce this chart, read at the birth instant. Subtract it back to recover the tropical positions, or compare it against your reference software to confirm you are in the same frame before chasing a placement difference.
  num get ayanamsaDegrees => read(json, 'ayanamsaDegrees', asNum);
}

/// Position details for a single upagraha (sub-planet)
extension type UpagrahaResponseSunBasedItem.fromJson(Map<String, Object?> json)
    implements Object {
  /// Upagraha name. Time-based: Gulika, Mandi, Kala, Mrityu, Ardhaprahara, Yamaghantaka. Sun-based: Dhuma, Vyatipata, Parivesha, Indra Chapa, Upaketu.
  String get name => read(json, 'name', asString);

  /// Sidereal longitude in degrees (0 to 360). Used for house placement and aspect analysis.
  num get longitude => read(json, 'longitude', asNum);

  /// Zodiac sign (rashi) the upagraha occupies. One of 12 Vedic rashis from Aries to Pisces.
  String get rashi => read(json, 'rashi', asString);

  /// Degree position within the occupied rashi (0 to 30).
  num get degreeInSign => read(json, 'degreeInSign', asNum);

  /// Nakshatra (lunar mansion) the upagraha occupies. One of 27 Vedic nakshatras.
  String get nakshatra => read(json, 'nakshatra', asString);

  /// Nakshatra number (1 to 27). Ashwini = 1, Bharani = 2, through Revati = 27.
  num get nakshatraIndex => read(json, 'nakshatraIndex', asNum);

  /// Pada (quarter) within the nakshatra (1 to 4). Each pada spans 3 degrees 20 minutes.
  num get nakshatraPada => read(json, 'nakshatraPada', asNum);
}

